contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: target address to receive potential transfer, and an amount of ETH sent with the call
    function run(address adr, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract can forward the requested ETH amount
        require(address(this).balance >= amount);

        // observe Owner before the call
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;

        // call multiplicate and record whether it reverted
        bool reverted;
        c.multiplicate{value: amount}(adr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe Owner after the call
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;

        // General invariant: multiplicate never changes the Owner public variable
        assert(ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

